import pandas as pd, numpy as np, statsmodels.formula.api as smf
df = pd.read_csv('data.csv')
pre = "log_hist_days + C(region) + log_pre_gmv + orders + cat_share + tenure + C(tier)"
df['did']=df.dY-df.dY_placebo
df['D2']=df.D**2; df['D3']=df.D**3

print("=== 1. 差分结果 did 的稳健性：不同控制集下 D 系数是否稳定 ===")
for f in ["did ~ D", f"did ~ D + {pre}", "did ~ D + log_hist_days + C(region)", "did ~ D + log_pre_gmv + orders + C(tier)"]:
    m=smf.ols(f,data=df).fit(cov_type='HC1'); print(f"{f:60s} D={m.params['D']:+.4f}({m.bse['D']:.4f})")
print("\n--- 对照：未差分 dY ---")
for f in ["dY ~ D", f"dY ~ D + {pre}"]:
    m=smf.ols(f,data=df).fit(cov_type='HC1'); print(f"{f:60s} D={m.params['D']:+.4f}({m.bse['D']:.4f})")

print("\n=== 2. 函数形式比较（在 dY 与 did 上）===")
for y in ['dY','did']:
    for f in [f"{y} ~ D + {pre}", f"{y} ~ D + D2 + {pre}", f"{y} ~ D + D2 + D3 + {pre}", f"{y} ~ np.log(D) + {pre}", f"{y} ~ bs(D, df=5) + {pre}"]:
        try:
            m=smf.ols(f,data=df).fit(); print(f"  {f[:55]:55s} R2={m.rsquared:.4f} AIC={m.aic:.0f}")
        except Exception as e: print(e)

print("\n=== 3. 规模效应：各 tier 的 D 系数 vs 平均 GMV 规模 ===")
rows=[]
for lev,sub in df.groupby('tier'):
    m=smf.ols("dY ~ D + log_hist_days + C(region) + log_pre_gmv + orders + cat_share + tenure",data=sub).fit(cov_type='HC1')
    g=np.exp(sub.log_pre_gmv).mean()
    rows.append((lev,len(sub),m.params['D'],m.bse['D'],g,m.params['D']/g))
for r in rows: print(f"tier={r[0]} n={r[1]:5d} beta_D={r[2]:+.4f}({r[3]:.4f}) 平均GMV={r[4]:8.2f} beta/GMV={r[5]:+.5f}")
print("\nrel=dY/exp(log_pre_gmv) 模型：")
df['rel']=df.dY/np.exp(df.log_pre_gmv); df['rel_did']=df.did/np.exp(df.log_pre_gmv)
for y in ['rel','rel_did']:
    m=smf.ols(f"{y} ~ D + {pre}",data=df).fit(cov_type='HC1')
    print(f" {y:8s} D={m.params['D']:+.5f}({m.bse['D']:.5f}) → 每多1天 GMV 变化 {m.params['D']*100:+.3f}%")
